from summary_lib import *

def add(chap, sub):
    chap("Gloss", "Glossary of Financial Terms & extra facts", "—", 2)
    sub("Glossary A–C", 2,
      T(["Term","Meaning"],
        [["Accrued interest","Interest since last coupon; buyer compensates seller"],["Admission to dealing","Permission to list and trade a company's securities"],
         ["Allotment advice","Letter confirming allotment; not negotiable"],["American option","Exercisable any time before expiry"],
         ["Analyst","Regularly publishes research-based recommendations"],["Arbitration","Exchange dispute mechanism between members and clients"],
         ["Asset management company","Runs day-to-day operations and investments of a unit trust"],["Auction","Buying-in securities for a seller who failed to deliver"],
         ["Authorised capital","Maximum capital allowed by MoA/AoA"],["Back office","Post-trade functions (some risk work moved to 'middle office')"],
         ["Banker to an issue","Scheduled bank: applications, allotment/call money, refunds, dividend/interest warrants"],
         ["Basis","Spot price − futures price; hedge reduces risk if basis is less volatile than price"],
         ["Basis point","1/100 of 1% (5.25% → 5.33% = 8 bp)"],["Bear / bear market","Expects fall (may sell what he does not own) / falling, sellers dominate"],
         ["Beta","Volatility vs market index; low beta = lower risk"],["Blue chip","Best-rated shares: return, safety, liquidity"],
         ["Bonus shares","Free shares from capitalised reserves"],["Book closure","Register closed to fix entitlements"],
         ["Book runner","Lead merchant banker maintaining the book"],["Book value","Cost less depreciation; firm: assets − liabilities"],
         ["Boom / bubble / break","Rising active market / speculative rise likely to burst / sharp fall"],
         ["Breadth of market","Number of regularly traded securities"],["Broker","Agent of clients but deemed principal — dual responsibility"],
         ["Brokerage","Commission; exchange scale is the <b>maximum</b>"],["Broker dealer","Non-bank trading for self or others"],
         ["Bull / bull market","Expects rise / rising, buyers dominate"],["Buy on margin","Buy with money borrowed from broker"],
         ["Churning","Excess trading by broker for commission; or heavy trading with no trend"],
         ["Circular trading","Matched fake trades to move prices, no real change in ownership"],
         ["Clearing","Working out what members deliver and receive"],["Closing price","Last trade price before close"],
         ["Confirmation process","Verifying trade details with counterparty"],["Counterparty risk","Other side fails before settlement"]]))
    sub("Glossary D–O", 2,
      T(["Term","Meaning"],
        [["Daily margin","Daily deposit set by exchange"],["Delisting","Permanent removal from exchange; voluntary delisting by promoter/acquirer"],
         ["Dealer","Counterparty on both sides of the market"],["Depository / DP","Keeps records of securities / its SEBI-registered agent"],
         ["Depreciation","Fall in value of a security, index or currency"],["Depth of market","Shares tradable at best bid/offer"],
         ["Ex-dividend date","From this date buyer gets no declared dividend"],["Ex-right date","Quotation marked XR"],
         ["Face value","Nominal or par value"],["Firm allotment","Firm-basis allotment to institutions, MFs, FPIs, NRIs, OCBs, employees"],
         ["Float / floating stock","Issued shares outstanding / part that trades daily"],["Hedge funds","Private aggressive pools; managers share profits"],
         ["Insider trading","Trading on undisclosed material information"],["ISIN","Unique ID for each security in depository system"],
         ["Listed company","Securities listed via offer document; includes listed PSUs"],["Market maker","Gives two-way quotes, obliged to deal"],
         ["Matched transaction","Members' reported buys and sells agree"],
         ["MIBOR","Mumbai Interbank Offer Rate — average of quotes from ~<b>30</b> banks"],["Odd lot","Less than standard trading unit"],
         ["Offer document","RHP, prospectus, shelf prospectus (public issue); letter of offer (rights)"],
         ["Offer period","From MoU/public announcement to completion of offer"],["Offer price","Price at which securities/units are offered"],
         ["Open order","Valid until executed or cancelled"],["Order book","Electronic book of demand and supply at each price"]]))
    sub("Glossary P–V", 2,
      T(["Term","Meaning"],
        [["Pari passu","New securities with same rights as existing ones"],["Pay-in / pay-out","Days members pay / receive"],
         ["Position limit","Max option contracts on one security held by investor(s) acting jointly"],
         ["Price-sensitive information","Likely to materially affect price if published"],["Prospectus","Any document inviting public to subscribe or deposit"],
         ["Proxy","Votes on behalf of a shareholder"],["Regulatory sandbox","Live controlled testing of FinTech under regulator"],
         ["Rolling settlement","Settle a fixed number of days after trade"],["SLBM","Exchange platform for anonymous securities lending, guaranteed settlement"],
         ["Short position","Sold for future delivery; option writer may be assigned"],["Stock split","More shares, lower price to raise demand"],
         ["Trading member","Derivatives member settling via a clearing member"],["Underwriting","Agreement to subscribe what public/holders don't"],
         ["Value at Risk","Max loss over a horizon at a low set probability"],["Vanilla issue","Straight conventional fixed-rate issue"],
         ["Volume of trading","Shares changing hands"],["Voting rights","Shareholder's right to vote at general meeting"]]) +
      K("Glossary compiled from SEBI's Glossary of the Capital Market, SEBI regulations and exchange websites"))
    sub("Footnote facts worth a mark", 3,
      L("Exam on or after <b>30 Oct 2026</b> uses the Sept 2026 workbook (updates highlighted yellow)",
        "Derivatives are 'created by exchanges' (footnote 5); 'portfolio' = group of securities",
        "Large/mid/small-cap list: AMFI publishes every <b>6 months</b> (end-June and end-December data), within <b>5 calendar days</b>; average full market cap of previous 6 months; multiple listings → average across exchanges",
        "Scheme names may not stress only returns (no 'High Yield', 'Credit Opportunities', 'Credit Advantage')",
        "Liquid and overnight funds follow uniform NAV cut-off rules (26 Nov 2010)",
        "ASBA extended from public issues to MF NFOs",
        "SEBI MF categorisation master circular: 20 Mar 2026; sectoral debt funds: 26 Feb 2026"))
